// Deterministic match score from the per-position model.
// Each requirement that the restaurant actually set is one scored dimension.
const d = $json;
const reqs        = d.requirements || {};
const candShifts  = Array.isArray(d.cand_shifts) ? d.cand_shifts : [];
const candPos     = Array.isArray(d.cand_positions) ? d.cand_positions : [];
const languages   = Array.isArray(d.languages) ? d.languages : [];
const WEEKEND     = 'סופ\"ש';

const expRank = { none: 0, '1_plus': 1, '2_plus': 2, '3_plus': 3, '5_plus': 5 };

let met = 0, total = 0;
const highlights = [];

// 1) Experience
if (reqs.experience) {
  total++;
  const need = expRank[reqs.experience] ?? 0;
  const have = expRank[d.experience] ?? 0;
  if (have >= need) met++;
}
if (d.experience && d.experience !== 'none') {
  highlights.push({ icon: '💼', text: `ניסיון: ${d.experience.replace('_plus', '+ שנים')}` });
}

// 2) Shifts-per-week commitment
if (reqs.shifts_min) {
  total++;
  if (candShifts.length >= reqs.shifts_min) met++;
}
if (candShifts.length) {
  highlights.push({ icon: '📅', text: `זמין/ה ל-${candShifts.length} משמרות` });
}

// 3) Weekend availability
if (reqs.weekends === true) {
  total++;
  const ok = candShifts.includes(WEEKEND);
  if (ok) met++;
  highlights.push({ icon: '🎉', text: ok ? 'זמין/ה לסופי שבוע' : 'אין זמינות לסופ\"ש' });
}

// 4) Wage fit (candidate's minimum <= what this position pays)
if (d.hourly_rate) {
  total++;
  if (!d.min_hourly_rate || d.min_hourly_rate <= d.hourly_rate) met++;
}

// 5) Position interest (candidate listed this role among the ones they want)
if (d.position_name) {
  total++;
  if (candPos.includes(d.position_name)) met++;
}

// Context-only highlights
if (languages.length) highlights.push({ icon: '🗣️', text: languages.join(' + ') });
if (d.city)           highlights.push({ icon: '📍', text: d.city });

const score = total === 0 ? 50 : Math.round((met / total) * 100);

return {
  application_id:    d.application_id,
  restaurant_id:     d.restaurant_id,
  position_id:       d.position_id,
  candidate_user_id: d.candidate_user_id,
  score, met, req: total,
  highlights,
  facts: {
    name: d.name,
    city: d.city,
    experience: d.experience,
    position: d.position_name,
    shifts: candShifts,
    shifts_per_week: candShifts.length,
    weekends: candShifts.includes(WEEKEND),
    languages,
    score, met, req: total
  }
};

// Merge the match data (from 'Compute match') with the LLM summary.
// Falls back to a deterministic sentence if the Claude call failed/returned nothing.
const m = $('Compute match').item.json;

let summary = '';
try { summary = ($json?.content?.[0]?.text || '').trim(); } catch (e) {}

if (!summary) {
  const f = m.facts;
  const parts = [`היי! ${f.name}${f.city ? ` מ${f.city}` : ''}.`];
  if (f.position)             parts.push(`התעניינ/ה במשרת ${f.position}.`);
  if (f.shifts_per_week)      parts.push(`זמין/ה ל-${f.shifts_per_week} משמרות בשבוע.`);
  if (f.experience && f.experience !== 'none')
                              parts.push(`ניסיון: ${String(f.experience).replace('_plus', '+ שנים')}.`);
  if (f.weekends)             parts.push('זמין/ה לסופי שבוע.');
  summary = parts.join(' ');
}

return {
  restaurant_id:     m.restaurant_id,
  application_id:    m.application_id,
  position_id:       m.position_id,
  candidate_user_id: m.candidate_user_id,
  match_score:       m.score,
  summary,
  highlights:        JSON.stringify(m.highlights),
  met_count:         m.met,
  req_count:         m.req,
  status:            'new'
};
